from functools import lru_cache
from itertools import combinations
import random, pickle, os, time
K=1
@lru_cache(None)
def kd(fs):
    if len(fs)<=1: return True
    fs=tuple(fs); D=fs[0].bit_count()
    cand=set()
    for f in fs:
        bits=[i for i in range(f.bit_length()) if f>>i&1]
        for s in range(1,min(K+1,D)+1):
            cand.update(sum(1<<i for i in c) for c in combinations(bits,s))
    for s in sorted(cand,key=int.bit_count):
        dele=tuple(f for f in fs if f&s!=s)
        if not dele:continue
        star=[f for f in fs if f&s==s]
        ok=True
        for f in star:
            for i in range(s.bit_length()):
                if s>>i&1:
                    r=f^(1<<i)
                    if not any(r&g==r for g in dele):ok=False;break
            if not ok:break
        if ok and kd(dele) and kd(tuple(sorted(f^s for f in star))):return True
    return False

def trial(n,d,steps):
    allf=[sum(1<<i for i in c) for c in combinations(range(n),d+1)]
    for it in range(steps):
        fs=(random.choice(allf),)
        while len(fs)<len(allf):
            cand=[f for f in allf if f not in fs]; random.shuffle(cand)
            for f in cand:
                new=tuple(sorted(fs+(f,)))
                if kd(new):fs=new;break
            else:
                print('STUCK',n,d,K,len(fs),fs,flush=True);return fs
        if it%10==0:print('trial',it,'cache',kd.cache_info(),flush=True)
    return None
if __name__=='__main__':
    trial(7,3,50)

