    for f in fs:
        bits=[1<<i for i in range(f.bit_length()) if f>>i&1]
        for sz in range(1,min(K+1,D)+1):
            cand.update(sum(c) for c in combinations(bits,sz))
    for s in sorted(cand,key=int.bit_count):
        dele=tuple(f for f in fs if f&s!=s)
        if not dele:continue
        star=[f for f in fs if f&s==s]
