from functools import lru_cache
from itertools import combinations

@lru_cache(None)
def decomposable(facets, k):
    if len(facets) == 1:
        return True
    candidates = set()
    for f in facets:
        s = f
        while s:
            if s.bit_count() <= k + 1:
                candidates.add(s)
            s = (s - 1) & f
    for s in candidates:
        deletion = tuple(f for f in facets if f & s != s)
        if not deletion:
            continue
        star = tuple(f for f in facets if f & s == s)
        # These are exactly the maximal potential lower-dimensional
        # faces left by deleting s. Each must be supported by deletion.
        pure = all(any((f ^ b) & g == (f ^ b) for g in deletion)
                   for f in star
                   for b in (1 << i for i in range(s.bit_length()) if s >> i & 1))
        if pure and decomposable(deletion, k):
            link = tuple(sorted(f ^ s for f in star))
            if decomposable(link, k):
                return True
    return False

@lru_cache(None)
def shellable(facets):
    if len(facets) == 1:
        return True
    q = facets[0].bit_count()
    if q == 0:
        return True
    for f in facets:
        remaining = tuple(g for g in facets if g != f)
        intersection = {f & g for g in remaining}
        maximal = {a for a in intersection
                   if not any(a != b and a & b == a for b in intersection)}
        if all(a.bit_count() == q - 1 for a in maximal) and shellable(remaining):
            return True
    return False

def check(n, d):
    universe = tuple(sum(1 << v for v in c) for c in combinations(range(n), d + 1))
    count = 0
    good = set()
    for mask in range(1, 1 << len(universe)):
        facets = tuple(sorted(f for i, f in enumerate(universe) if mask >> i & 1))
        a = shellable(facets)
        b = decomposable(facets, d)
        assert a == b, (facets, a, b)
        if a:
            good.add(mask)
        count += 1
    # This only checks same-vertex completion for this finite universe.
    full = (1 << len(universe)) - 1
    stuck = [m for m in good if m != full and
             not any(m | (1 << i) in good for i in range(len(universe)) if not (m >> i & 1))]
    print({'n':n, 'd':d, 'complexes_checked':count,
           'shellable_and_d_decomposable':len(good), 'stuck_shellable_complexes':len(stuck)})

if __name__ == '__main__':
    check(5, 2)
    check(6, 3)

