def boolean_search(n=8,d=3,trials=100):
    import random
    F=list(itertools.combinations(range(n),d+1)); m=len(F)
    FS=[frozenset(f) for f in F]
    faces=[tuple(c) for size in range(1,d+1) for c in itertools.combinations(range(n),size)]
    containing={g:[i for i in range(m) if set(g)<=FS[i]] for g in faces}
    adj=[[h for h in range(m) if len(FS[i]&FS[h])==d] for i in range(m)]
    x=[Bool('x%d'%i) for i in range(m)]
    y={g:Bool('y'+'_'.join(map(str,g))) for g in faces}
    base=[]
    for g in faces:base.append(y[g]==Or([x[i] for i in containing[g]]))
    base.extend(y[(v,)] for v in range(n));base.append(x[0]);base.append(Not(And(x)))
    for i,f in enumerate(F):
        ridges=list(itertools.combinations(f,d))
        small=[g for size in range(1,d) for g in itertools.combinations(f,size)]
        blockers=[And(y[g],*[Not(y[r]) for r in ridges if set(g)<=set(r)]) for g in small]
        base.append(Implies(Not(x[i]),Or(blockers)))
    print('boolean built',n,d,m,flush=True)
    for trial in range(trials):
        order=list(range(1,m));random.shuffle(order);order=[0]+order
        rank={j:i for i,j in enumerate(order)}
        s=Solver();s.set(timeout=3000);s.add(base)
        for pos,i in enumerate(order):
            before=[h for h in adj[i] if rank[h]<pos]
            for j in order[:pos]:
                if j in before:continue
                inter=FS[i]&FS[j]
                witness=[x[h] for h in before if inter<=FS[h]]
                s.add(Or(Not(x[i]),Not(x[j]),*witness))
        res=s.check()
        if trial%10==0:print('trial',trial,res,flush=True)
        if res==sat:
            mod=s.model();selected=[F[i] for i in order if is_true(mod.eval(x[i]))]
            print('FOUND',len(selected),selected,flush=True)
            json.dump({'n':n,'d':d,'facets':selected},open('sat_example.json','w'))
            return selected
    return None

if __name__=='__main__': boolean_search(8,3,100)

